CSS="""*{box-sizing:border-box}body{margin:0;background:#0d1320;color:#eef4fc;font:1rem/1.6 system-ui,sans-serif}main{max-width:780px;margin:auto;padding:24px}h1,h2{line-height:1.2;overflow-wrap:anywhere}fieldset{border:1px solid #61728a;border-radius:14px;padding:16px;margin:24px 0;min-width:0}.fields,.results{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,230px),1fr));gap:16px}.field{display:grid;gap:6px;min-width:0}input:not([type=checkbox]){width:100%;padding:12px;background:#152338;border:1px solid #8192aa;border-radius:8px;color:inherit;font:inherit}input[aria-invalid=true]{border:2px solid #f8aa96}.toggle{display:flex;align-items:flex-start;gap:8px;margin-top:16px}.toggle input{width:20px;height:20px;flex:none;accent-color:#39e1c6}button{padding:10px 16px;margin:12px 8px 0 0;background:#18364a;color:inherit;border:1px solid #8192aa;border-radius:8px;font:inherit;cursor:pointer}button:focus-visible,input:focus-visible{outline:3px solid #39e1c6;outline-offset:3px}.results>div{padding:16px;border:1px solid #61728a;border-radius:12px;min-width:0}output{display:block;font-size:clamp(1.25rem,4vw,1.8rem);font-weight:700;color:#8ef5df;overflow-wrap:anywhere}small{display:block;color:#b8c8da}"""
JS="""(()=>{"use strict";const ids=['rent','utilities','deposit','oneoff'];const fields=ids.map(id=>document.getElementById(id));const pre=document.getElementById('prepay');const monthly=document.getElementById('monthly');const upfront=document.getElementById('upfront');const status=document.getElementById('status');const nf=new Intl.NumberFormat(document.documentElement.lang==='ru'?'ru-RU':'en-US');const format=n=>nf.format(n)+' ฿';function render(){const vals=fields.map(x=>{const s=x.value;const n=Number(s);const ok=/^[0-9]+$/.test(s)&&Number.isSafeInteger(n)&&n>=0&&n<=1000000000;x.setAttribute('aria-invalid',ok?'false':'true');return ok?n:null;});if(vals.includes(null)){monthly.textContent='—';upfront.textContent='—';status.textContent=status.dataset.invalid;return;}const [r,u,d,o]=vals;monthly.textContent=format(r+u);upfront.textContent=format(r+d+o+(pre.checked?u:0));status.textContent=status.dataset.ready;}fields.forEach(x=>x.addEventListener('input',render));pre.addEventListener('change',render);document.getElementById('example').addEventListener('click',()=>{[28000,3000,56000,2000].forEach((n,i)=>{fields[i].value=String(n);});pre.checked=false;render();});document.getElementById('reset').addEventListener('click',()=>{fields.forEach(x=>{x.value='';});pre.checked=false;render();fields[0].focus();});render();})();"""
def pin(s):return base64.b64encode(hashlib.sha256(s.encode()).digest()).decode()
def render(locale):
 c=COPY[locale];e=lambda x:html.escape(x,quote=True)
 fields="".join(f'<div class="field"><label for="{i}">{e(label)} (THB)</label><input id="{i}" type="number" inputmode="numeric" min="0" max="1000000000" step="1" autocomplete="off" aria-describedby="status"></div>' for i,label in zip(("rent","utilities","deposit","oneoff"),c["labels"]))
 csp=f"default-src 'none'; script-src 'sha256-{pin(JS)}'; style-src 'sha256-{pin(CSS)}'; connect-src 'none'; form-action 'none'; base-uri 'none'; object-src 'none'"
 return (f'<!doctype html><html lang="{locale}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta http-equiv="Content-Security-Policy" content="{e(csp)}"><title>{e(c["title"])}</title><style>{CSS}</style></head><body><main><h1>{e(c["title"])}</h1><p>{e(c["intro"])}</p><fieldset><legend>THB</legend><div class="fields">{fields}</div><label class="toggle"><input id="prepay" type="checkbox"> {e(c["prepay"])}</label><button id="example" type="button">{e(c["example"])}</button><button id="reset" type="button">{e(c["reset"])}</button></fieldset><div class="results" aria-live="polite"><div><strong>{e(c["monthly"])}</strong><output id="monthly">—</output></div><div><strong>{e(c["upfront"])}</strong><output id="upfront">—</output></div></div><p id="status" role="status" data-invalid="{e(c["invalid"])}" data-ready="{e(c["ready"])}">{e(c["invalid"])}</p><p>{e(c["note"])}</p><small>{e(c["privacy"])}</small></main><script>{JS}</script></body></html>\n').encode()
def build(manifest):
 if manifest["release_id"]!=PARENT or manifest["payload_sha256"]!=PAYLOAD:raise ValueError("parent release drift")
 return {l+"/rental-budget-calculator.html":render(l) for l in COPY}
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument("--repo",required=True,type=Path);p.add_argument("--output",required=True,type=Path);a=p.parse_args()
 repo=a.repo.resolve();out=a.output.resolve();git=lambda *args:subprocess.check_output(["git","-C",str(repo),*args])
 if git("rev-parse",BASE+"^{commit}").decode().strip()!=BASE:raise ValueError("Git baseline")
 if out==repo or repo in out.parents or out.exists():raise ValueError("new output outside repository required")
 pages=build(json.loads(git("show",BASE+":deploy/live/_release.json")))
 out.mkdir(parents=True,exist_ok=False)
 for name,raw in pages.items():
  f=out/name;f.parent.mkdir(parents=True,exist_ok=True);f.write_bytes(raw)
if __name__=="__main__":main()
